    reader = csv.DictReader(f)
    for row in reader:
        sex_data[row['ID']] = row['SEX']

print(f'Total patients with sex info: {len(sex_data)}')

wbc_normal_males_abnormal_fg = set()

with open('csv/Laboratory.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        pid = row['ID']
        sex = sex_data.get(pid, '')
        if sex != 'M':
            continue

        wbc = row['WBC']
        wbc_normal = False
        if wbc and wbc != '':
            try:
                wbc_val = float(wbc)
                if 4 <= wbc_val <= 10:
                    wbc_normal = True
            except:
                pass

        if wbc_normal:
            fg = row['FG']
            if fg and fg != '':
                try:
                    fg_val = float(fg)
                    if fg_val < 2 or fg_val > 4:
                        wbc_normal_males_abnormal_fg.add(pid)
                except:
                    pass

print(f'Male patients with normal WBC but abnormal FG: {len(wbc_normal_males_abnormal_fg)}')

